      <div style={{ display: "flex", alignItems: "center", gap: "0.75rem", cursor: "pointer" }} onClick={onBack}>
        <div style={{
          width: "40px", 
          height: "40px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          overflow: "hidden"
        }}>
          <img 
            src={logoImg} 
            alt="SmartChef Logo" 
            style={{ width: "100%", height: "100%", objectFit: "contain" }} 
          />
        </div>
